#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/android/tasks/test-e2e-android.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Run the instrumented Android tests on a Gradle managed device, or on the connected device"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def main():
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # Shipped with the android tool. It acts on the Gradle build at the root
  # only: the android/ folder of a Flutter app is for the flutter tool. The
  # part has no flag, because test:e2e passes the same arguments to each part.
  # It reads these values, with a default; a repository sets them in the [env]
  # of .config/mise/conf.d/zz-repo/mise.<env>.toml:
  #   ANDROID_VARIANT    the build variant whose androidTest source set runs
  #                      (debug)
  #   ANDROID_DEVICE     the managed device of testOptions.managedDevices (e2e)
  #   ANDROID_CONNECTED  true runs connected<Variant>AndroidTest on the device
  #                      or emulator already attached, and ANDROID_DEVICE does
  #                      not apply (false)
  #
  # Without an executable ./gradlew or without a src/androidTest folder in a
  # module, the part does not apply and prints nothing.
  if not os.access("gradlew", os.X_OK):
    sys.exit(0)
  # A failed git stops the task, with the error of git.
  result = subprocess.run(
    [
      "git",
      "-c",
      "core.quotePath=off",
      "ls-files",
      "--cached",
      "--others",
      "--exclude-standard",
      "--",
      "src/androidTest/*",
      "*/src/androidTest/*",
    ],
    check=False,
    stdout=subprocess.PIPE,
  )
  if result.returncode != 0:
    sys.exit(exit_code(result.returncode))
  if not result.stdout.strip(b"\n"):
    sys.exit(0)

  variant = os.environ.get("ANDROID_VARIANT") or "debug"
  device = os.environ.get("ANDROID_DEVICE") or "e2e"
  variant_name = variant[:1].upper() + variant[1:]
  connected = os.environ.get("ANDROID_CONNECTED", "false") == "true"

  if connected:
    task = f"connected{variant_name}AndroidTest"
    helpers.print_header(f"Running {task} on the connected device ...")
  else:
    task = f"{device}{variant_name}AndroidTest"
    helpers.print_header(f"Running {task} on the managed device {device} ...")

  android_home = os.environ.get("ANDROID_HOME", "")
  if not android_home or not os.path.isdir(f"{android_home}/platforms"):
    helpers.print_error(f"test:e2e: no Android SDK at ANDROID_HOME ({android_home or 'unset'}).")
    helpers.print_yellow("Run: mise run setup")
    sys.exit(1)

  gradle_args = []
  # A CI runner has no GPU; the software renderer keeps the managed emulator
  # deterministic there.
  if not connected and os.environ.get("CI", ""):
    gradle_args.append("-Pandroid.testoptions.manageddevices.emulator.gpu=swiftshader_indirect")

  result = subprocess.run(["./gradlew", *gradle_args, task], check=False)
  sys.exit(exit_code(result.returncode))


main()
